<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/credits.php';$current=tuman_require_role('TEACHER');$credits=tuman_teacher_credits(tuman_database(),$current['id']);tuman_teacher_page_start('Credits and refunds');?><h1>Credits and refunds</h1><p><a class="button" href="/Tuman/teacher/advance-create.php">Record advance</a></p><p>Record an advance before an invoice exists, or manage an overpayment credit. Unused credit can be applied to a future invoice or refunded to the Student.</p><?php if($credits===[]):?><p>No credits have been created.</p><?php else:?><table><thead><tr><th>Student</th><th>Source</th><th>Received</th><th>Currency</th><th>Original</th><th>Remaining</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($credits as $c):?><tr><td><?=htmlspecialchars(trim($c['first_name'].' '.($c['last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($c['source_type']==='ADVANCE'?'Advance':'Overpayment',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($c['received_date']??substr($c['created_at'],0,10),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($c['currency_code'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(tuman_invoice_money_label($c['original_amount'],$c['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(tuman_invoice_money_label($c['remaining_amount'],$c['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($c['status'],ENT_QUOTES,'UTF-8')?></td><td><?php if($c['status']==='ACTIVE'):?><a href="/Tuman/teacher/credit-apply.php?id=<?=(int)$c['id']?>">Apply</a> <a href="/Tuman/teacher/credit-refund.php?id=<?=(int)$c['id']?>">Refund</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif; tuman_teacher_page_end(); ?>
